// ---------------------------------------------------------------------------
// Webhook transport (spectrum.webhook)
// ---------------------------------------------------------------------------

/**
 * Request-scoped handler invoked once per inbound message that
 * `spectrum.webhook()` resolves. Receives the same fully-built `[space,
 * message]` pair that `spectrum.messages` yields.
 *
 * Runs **fire-and-forget**: it is dispatched after the HTTP response (the
 * platform's `respond()` reply) has already been computed, so its outcome never
 * affects the response, and a throw is caught + logged rather than surfaced —
 * mirroring the body of a `for await (… of spectrum.messages)` loop.
 *
 * On a long-running server the event loop keeps the handler alive. On
 * serverless/edge runtimes the function may be frozen once the response is
 * returned, so keeping background work alive is the caller's responsibility —
 * the usual pattern is to enqueue the work and process it in a separate worker.
 */
export type WebhookHandler = (
  space: Space,
  message: Message
) => void | Promise<void>;

/**
 * Raw webhook input for HTTP servers without Web `Request`/`Response` (Express,
 * raw Node). `body` MUST be the exact bytes POSTed — never a re-encoded
 * JSON/text body — so both the protobuf decode (fusor) and the HMAC
 * verification (native Spectrum webhook) work.
 *
 * `headers` ARE read for **native Spectrum webhooks**: `X-Spectrum-Signature` /
 * `X-Spectrum-Timestamp` carry the HMAC verified against
 * `Spectrum({ webhookSecret })`, and the signature header also selects the
 * native path. For **fusor** envelopes they are ignored (authenticity is the
 * per-platform `verify()` reading the inner reconstructed request). The natural
 * `{ headers: req.headers, body: req.body }` shape works for both.
 */
export interface WebhookRawRequest {
  body: Uint8Array | ArrayBuffer;
  headers?: Record<string, string>;
}

/** Raw webhook result, written back by the caller as the HTTP response. */
export interface WebhookRawResult {
  body: Uint8Array;
  headers: Record<string, string>;
  status: number;
}

import { stubCloud } from "@spectrum-ts/test-support/cloud";
import { encodeEvent, makeSlack } from "@spectrum-ts/test-support/fusor";
import {
  baseConfig,
  makeManagedProvider,
} from "@spectrum-ts/test-support/platform";
import { flush } from "@spectrum-ts/test-support/timing";
import {
  SPECTRUM_WEBHOOK_SECRET,
  signSpectrum,
  textEnvelope,
} from "@spectrum-ts/test-support/webhook";
import { describe, expect, it } from "vitest";
import { Spectrum } from "@/spectrum";
import type { Message } from "@/types/message";

stubCloud();

// The env fallback must not leak in from the host so the missing-secret path is
// exercised deterministically (empty string is falsy → treated as unset).
process.env.SPECTRUM_WEBHOOK_SECRET = "";

const PLATFORM = "im";
const NO_FUSOR_PROVIDER_ERROR = /no fusor provider is configured/;

const withSpectrum = async (
  overrides: Record<string, unknown>,
  fn: (spectrum: Awaited<ReturnType<typeof Spectrum>>) => Promise<void>
) => {
  const spectrum = await Spectrum({
    ...baseConfig,
    providers: [makeManagedProvider(PLATFORM).config({})],
    ...overrides,
  });
  try {
    await fn(spectrum);
  } finally {
    await spectrum.stop();
  }
};

describe("spectrum.webhook (native Spectrum webhook)", () => {
  it("verifies, deserializes, and delivers a signed message", async () => {
    await withSpectrum(
      { webhookSecret: SPECTRUM_WEBHOOK_SECRET },
      async (spectrum) => {
        const received: [unknown, Message][] = [];
        const { promise: finished, resolve: done } =
          Promise.withResolvers<void>();

        const signed = signSpectrum(textEnvelope(PLATFORM, "hello there"));
        const result = await spectrum.webhook(signed, (space, message) => {
          received.push([space, message]);
          done();
        });
        await finished;

        expect(result.status).toBe(200);
        expect(received).toHaveLength(1);
        const [space, message] = received[0] ?? [];
        expect((space as { __platform: string }).__platform).toBe(PLATFORM);
        expect(message?.direction).toBe("inbound");
        expect(message?.content).toEqual({ type: "text", text: "hello there" });
      }
    );
  });

  it("rejects a bad signature with 401 and never calls the handler", async () => {
    await withSpectrum(
      { webhookSecret: SPECTRUM_WEBHOOK_SECRET },
      async (spectrum) => {
        let called = false;
        const signed = signSpectrum(textEnvelope(PLATFORM, "hi"), {
          secret: "the-wrong-secret",
        });
        const result = await spectrum.webhook(signed, () => {
          called = true;
        });
        await flush();

    this.reconnectResolve = undefined;
  }

  private async runWebsocketOnce(): Promise<void> {
    if (!this.tokenProvider) {
      throw new Error("fusor: token not initialized");
    }
    const token = await this.tokenProvider.getToken();
    const session = runFusorWsSession({
      url: this.websocketEndpoint,
      token,
      onEvent: async (event, sendReply) => {
        if (this.stopped) {
          return;
        }
        const reply = await this.processEvent(event);
        // The server answers unexpected replies with typed notices —
        // only reply when asked (sendReply is set iff replyExpected).
        sendReply?.(reply);
      },
    });
    this.wsSession = session;
    try {
      await session.done;
    } finally {
      this.wsSession = undefined;
    }
  }

  // Transport-independent event processing: route by platform, parse the wire
  // request, run every registered handler (verify → messages), and combine the
  // results into a single InboundReply. Returns the reply instead of writing it
  // anywhere, so both the streaming session (sendReply) and the synchronous
  // webhook path can drive it. `deliver` controls where produced records go:
  // the streaming path defaults to each handler's pushMessage (the per-platform
  // queue feeding spectrum.messages); the webhook path collects them for the
  // request instead.
  async processEvent(
    event: RawInboundEvent,
    deliver?: (record: ProviderMessageRecord) => void
  ): Promise<InboundReply> {
    const handlers = this.handlers.get(event.platform) ?? [];
    if (handlers.length === 0) {
      // Reply shape stays wire-compatible; only the local log gets the
      // install hint (since v5 the official providers are separate packages,
      // so "no handler" is usually a missing install, not a routing bug).
      const hint = officialProviderInstallHint(event.platform);
      log.warn(
        hint
          ? `fusor: no handler for platform — ${hint}`
          : "fusor: no handler for platform",
        {
          "spectrum.fusor.platform": event.platform,
          "spectrum.fusor.event_id": event.eventId,
        }
      );
      return {
        eventId: event.eventId,
        errorReason: `no handler for platform ${event.platform}`,
        status: 0,
        headers: {},
        body: new Uint8Array(0),
      };
    }

    let parsedRequest: ParsedHttpRequest;
    try {
      parsedRequest = parseHttpRequest(event.rawRequest);
    } catch (error) {
      const errorReason = errorText(error);
      log.warn("fusor: failed to parse raw_request", {
        "spectrum.fusor.platform": event.platform,
        "spectrum.fusor.event_id": event.eventId,
        ...errorAttrs(error),
      });
      return {
        eventId: event.eventId,
        errorReason,
        status: 0,
        headers: {},
        body: new Uint8Array(0),
      };
    }

    const outcomes = await Promise.all(
      handlers.map((handler) => runHandlerOnce(handler, parsedRequest, deliver))
    );

    const combined = combineReplies(outcomes);
    combined.eventId = event.eventId;
    return combined;
  }

  async close(): Promise<void> {
    if (this.stopped) {
      return;
    }
    this.stopped = true;
    this.wsSession?.close();
    // Wake an in-progress reconnect backoff so the loop observes stopped and
    // exits immediately instead of waiting out the timer.
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = undefined;
    }
    this.reconnectResolve?.();
    this.reconnectResolve = undefined;
    if (this.tokenProvider) {
      await this.tokenProvider.dispose();
    }
    if (this.connectionLoop) {
      await this.connectionLoop;
    }
    this.stopResolve?.();
  }

  async waitStopped(): Promise<void> {
    return this.stoppedPromise;
  }
}

