import { v } from "convex/values";
import { type MutationCtx, mutation, query } from "./_generated/server.js";
import {
  cancelCurrentChain,
  DEFAULT_DEBOUNCE_MS,
  scheduleFlush,
} from "./pipeline.js";

/**
 * The inbound half of the pipeline: durable dedupe, the batch queue, and the
 * space registry.
 *
 * The HTTP entry point verifies a delivery and calls `enqueue` before it
 * answers 200, so a message is durable the moment Spectrum Cloud is told the
 * delivery succeeded. That's the whole reason the component exists rather than
 * an `app.webhook()` adapter: core's webhook handler is fire-and-forget *after*
 * the response, and on a serverless runtime the isolate is frozen the instant
 * the response is returned.
 */

const messageArgs = {
  spaceId: v.string(),
  messageId: v.string(),
  platform: v.string(),
  senderId: v.optional(v.string()),
  content: v.any(),
  timestamp: v.optional(v.string()),
  raw: v.optional(v.any()),
  phone: v.optional(v.string()),
  spaceType: v.optional(v.union(v.literal("dm"), v.literal("group"))),
};

const upsertSpace = async (
  ctx: MutationCtx,
  args: {
    spaceId: string;
    platform: string;
    phone?: string;
    spaceType?: "dm" | "group";
    now: number;
  }
): Promise<void> => {
  const existing = await ctx.db
    .query("spaces")
    .withIndex("by_space", (q) => q.eq("spaceId", args.spaceId))
    .unique();
  const patch = {
    platform: args.platform,
    lastInboundAt: args.now,
    // Routing facts are sticky: a later delivery that omits `phone` must not
    // erase the line we already learned, or sends to this space start failing
    // in multi-line mode.
    ...(args.phone === undefined ? {} : { phone: args.phone }),
    ...(args.spaceType === undefined ? {} : { type: args.spaceType }),
  };
  if (existing) {
    await ctx.db.patch(existing._id, patch);
    return;
  }
  await ctx.db.insert("spaces", {
    spaceId: args.spaceId,
    ...patch,
  });
};

/**
 * Record one verified inbound message and (re)arm the debounce window.
 *
 * Returns `{ deduped: true }` when the message id has been seen before —
 * native webhooks are at-least-once, so a redelivery must not create a second
 * queue row or restart the debounce timer.
 */
export const enqueue = mutation({
  args: {
    ...messageArgs,
    debounceMs: v.optional(v.number()),
    // Function handle (`createFunctionHandle(internal.foo.bar)`) for the app's
    // batch handler. Threaded through per-call rather than stored at install
    // time so the app can change or version its handler without a migration.
    onBatch: v.optional(v.string()),
  },
  returns: v.object({
    deduped: v.boolean(),
    cancelledChain: v.optional(v.string()),
  }),
  handler: async (ctx, args) => {
    const duplicate = await ctx.db
      .query("inbound")
      .withIndex("by_message", (q) => q.eq("messageId", args.messageId))
      .unique();
    if (duplicate) {
      return { deduped: true };
    }

    const now = Date.now();
    await upsertSpace(ctx, {
      spaceId: args.spaceId,
      platform: args.platform,
      ...(args.phone === undefined ? {} : { phone: args.phone }),
      ...(args.spaceType === undefined ? {} : { spaceType: args.spaceType }),
      now,
    });

    await ctx.db.insert("inbound", {
      spaceId: args.spaceId,
      messageId: args.messageId,
      platform: args.platform,
      ...(args.senderId === undefined ? {} : { senderId: args.senderId }),
      content: args.content,
      ...(args.timestamp === undefined ? {} : { timestamp: args.timestamp }),
      receivedAt: now,
      status: "queued" as const,
      ...(args.raw === undefined ? {} : { raw: args.raw }),
    });

    // A new message supersedes whatever turn is in flight: cancel it, carry
    // its drained messages forward, then restart the debounce window.
    const cancelledChain = await cancelCurrentChain(ctx, args.spaceId, now);
    await scheduleFlush(ctx, {
      spaceId: args.spaceId,
      debounceMs: args.debounceMs ?? DEFAULT_DEBOUNCE_MS,
      ...(args.onBatch === undefined ? {} : { onBatch: args.onBatch }),
      now,
    });

    return {
      deduped: false,
      ...(cancelledChain === undefined ? {} : { cancelledChain }),
    };
  },
});

/** Look up a space's routing record (phone/type) for the send path. */
export const getSpace = query({
  args: { spaceId: v.string() },
  returns: v.union(
    v.null(),
    v.object({
      spaceId: v.string(),
      platform: v.string(),
      phone: v.optional(v.string()),
      type: v.optional(v.union(v.literal("dm"), v.literal("group"))),
      lastInboundAt: v.number(),
    })
  ),
  handler: async (ctx, args) => {
    const space = await ctx.db
      .query("spaces")
      .withIndex("by_space", (q) => q.eq("spaceId", args.spaceId))
      .unique();
    if (!space) {
      return null;
    }
    return {
      spaceId: space.spaceId,
      platform: space.platform,
      ...(space.phone === undefined ? {} : { phone: space.phone }),
      ...(space.type === undefined ? {} : { type: space.type }),
      lastInboundAt: space.lastInboundAt,
    };
  },
});

/** Recent messages for a space, newest last. Intended for dashboards. */
export const listMessages = query({
  args: {
    spaceId: v.string(),
    limit: v.optional(v.number()),
  },
  returns: v.array(
    v.object({
      messageId: v.string(),
      senderId: v.optional(v.string()),
      content: v.any(),
      timestamp: v.optional(v.string()),
      receivedAt: v.number(),
      status: v.string(),
    })
  ),
  handler: async (ctx, args) => {
    const rows = await ctx.db
      .query("inbound")
      .withIndex("by_space_status", (q) => q.eq("spaceId", args.spaceId))
      .order("desc")
      .take(args.limit ?? 50);
    return rows.reverse().map((row) => ({
      messageId: row.messageId,
      ...(row.senderId === undefined ? {} : { senderId: row.senderId }),
      content: row.content,
      ...(row.timestamp === undefined ? {} : { timestamp: row.timestamp }),
      receivedAt: row.receivedAt,
      status: row.status,
    }));
  },
});

import { type FunctionHandle, createFunctionHandle } from "convex/server";
import { v } from "convex/values";
import type { Doc } from "./_generated/dataModel.js";
import { internal } from "./_generated/api.js";
import {
  type MutationCtx,
  internalMutation,
  mutation,
  query,
} from "./_generated/server.js";

/**
 * The batching pipeline.
 *
 * People text in bursts, so a reply per message produces overlapping answers
 * that never see the actual question. Every inbound message resets a debounce
 * timer; when it finally expires, one flush drains the whole burst and hands it
 * to the app as a single turn.
 *
 * Two rules from Photon's production architecture are load-bearing here:
 *
 * 1. **Drain in the handler, not the enqueuer.** Rows stay in `inbound` until
 *    a flush actually runs. A cancelled flush therefore loses nothing — the
 *    next one picks the same rows up.
 * 2. **Cancellation is per-chain, not per-space.** `cancelledAt` is compared
 *    against the chain's own `chainStartedAt` rather than read as a boolean,
 *    so a stale flag from a superseded turn can't orphan the turn that
 *    replaced it.
 */

export const DEFAULT_DEBOUNCE_MS = 5000;

/** Batch payload handed to the app's handler. */
export type BatchHandler = FunctionHandle<
  "action" | "mutation",
  {
    spaceId: string;
    chainId: string;
    messages: BatchMessage[];
    carried: BatchMessage[];
  },
  unknown
>;

export interface BatchMessage {
  messageId: string;
  senderId?: string;
  content: unknown;
  timestamp?: string;
}

const batchMessageValidator = v.object({
  messageId: v.string(),
  senderId: v.optional(v.string()),
  content: v.any(),
  timestamp: v.optional(v.string()),
});

const toBatchMessage = (
  row: Doc<"inbound"> | Doc<"carried">
): BatchMessage => ({
  messageId: row.messageId,
  ...(row.senderId === undefined ? {} : { senderId: row.senderId }),
  content: row.content,
  ...(row.timestamp === undefined ? {} : { timestamp: row.timestamp }),
});

const getInflight = async (
  ctx: MutationCtx,
  spaceId: string
): Promise<Doc<"inflight"> | null> =>
  await ctx.db
    .query("inflight")
    .withIndex("by_space", (q) => q.eq("spaceId", spaceId))
    .unique();

/**
 * Cancel whatever turn currently owns this space.
 *
 * Cancels the scheduled flush/handler jobs, flags the chain, and moves any
 * rows the chain had already drained into `carried` so the next batch still
 * sees them. `ctx.scheduler.cancel` cannot stop an action that is already
 * running — that case is handled cooperatively by `isCancelled`, which a
 * running handler polls between steps.
 *
 * Returns the cancelled chain id, if there was one.
 */
export const cancelCurrentChain = async (
  ctx: MutationCtx,
  spaceId: string,
  now: number
): Promise<string | undefined> => {
  const inflight = await getInflight(ctx, spaceId);
  if (!inflight) {
    return;
  }

  if (inflight.flushJobId) {
    await ctx.scheduler.cancel(inflight.flushJobId);
  }
  if (inflight.handlerJobId) {
    await ctx.scheduler.cancel(inflight.handlerJobId);
  }

  const chainId = inflight.chainId;
  if (chainId) {
    // Carry forward anything this chain drained but never answered.
    const drained = await ctx.db
      .query("inbound")
      .withIndex("by_chain", (q) => q.eq("chainId", chainId))
      .collect();
    for (const row of drained) {
      if (row.status !== "drained") {
        continue;
      }
      await ctx.db.insert("carried", {
        spaceId: row.spaceId,
        messageId: row.messageId,
        content: row.content,
        ...(row.senderId === undefined ? {} : { senderId: row.senderId }),
        ...(row.timestamp === undefined ? {} : { timestamp: row.timestamp }),
        carriedAt: now,
      });
      await ctx.db.patch(row._id, { status: "handled" as const });
    }

    // Sends queued by the dead chain must never go out.
    const queued = await ctx.db
      .query("outbox")
      .withIndex("by_chain", (q) => q.eq("chainId", chainId))
      .collect();
    for (const row of queued) {
      if (row.status !== "pending") {
        continue;
      }
      if (row.jobId) {
        await ctx.scheduler.cancel(row.jobId);
      }
      await ctx.db.patch(row._id, { status: "cancelled" as const });
    }
  }

  await ctx.db.patch(inflight._id, {
    cancelledAt: now,
    flushJobId: undefined,
    handlerJobId: undefined,
  });
  return chainId;
};

/** Arm (or re-arm) the debounce timer for a space. */
export const scheduleFlush = async (
  ctx: MutationCtx,
  args: {
    spaceId: string;
    debounceMs: number;
    onBatch?: string;
    now: number;
  }
): Promise<void> => {
  const jobId = await ctx.scheduler.runAfter(
    args.debounceMs,
    internal.pipeline.flush,
    {
      spaceId: args.spaceId,
      ...(args.onBatch === undefined ? {} : { onBatch: args.onBatch }),
    }
  );

  const inflight = await getInflight(ctx, args.spaceId);
  if (inflight) {
    await ctx.db.patch(inflight._id, { flushJobId: jobId });
    return;
  }
  await ctx.db.insert("inflight", { spaceId: args.spaceId, flushJobId: jobId });
};

/**
 * Debounce expired: drain the burst and start a chain.
 *
 * Carried messages come first so the app can present them as earlier context
 * rather than fresh input.
 */
export const flush = internalMutation({
  args: {
    spaceId: v.string(),
    onBatch: v.optional(v.string()),
  },
  returns: v.null(),
  handler: async (ctx, args) => {
    const queued = await ctx.db
      .query("inbound")
      .withIndex("by_space_status", (q) =>
        q.eq("spaceId", args.spaceId).eq("status", "queued")
      )
      .collect();
    const carriedRows = await ctx.db
      .query("carried")
      .withIndex("by_space", (q) => q.eq("spaceId", args.spaceId))
      .collect();

    if (queued.length === 0 && carriedRows.length === 0) {
      return null;
    }

    const now = Date.now();
    // Unique per turn, and derived from data already in the transaction —
    // component functions are deterministic, so no Math.random() here.
    const chainId = `${args.spaceId}:${now}:${queued[0]?._id ?? "carried"}`;

    for (const row of queued) {
      await ctx.db.patch(row._id, { status: "drained" as const, chainId });
    }
    const carried = carriedRows.map(toBatchMessage);
    for (const row of carriedRows) {
      await ctx.db.delete(row._id);
    }

    const inflight = await getInflight(ctx, args.spaceId);
    const inflightId =
      inflight?._id ??
      (await ctx.db.insert("inflight", { spaceId: args.spaceId }));
    await ctx.db.patch(inflightId, {
      chainId,
      chainStartedAt: now,
      cancelledAt: undefined,
      flushJobId: undefined,
    });

    if (!args.onBatch) {
      // No handler wired up: the messages are still durable and marked
      // drained, so a later chain carries them forward rather than losing them.
      return null;
    }

    const handlerJobId = await ctx.scheduler.runAfter(
      0,
      args.onBatch as BatchHandler,
      {
        spaceId: args.spaceId,
        chainId,
        messages: queued.map(toBatchMessage),
        carried,
      }
    );
    await ctx.db.patch(inflightId, { handlerJobId });
    return null;
  },
});

/**
 * Has this chain been superseded?
 *
 * The comparison is `cancelledAt > chainStartedAt` — not "is the flag set" —
 * so a flag left behind by an earlier turn cannot cancel the current one. A
 * long-running handler should poll this between steps (before generating,
 * before sending) and bail out when it returns true.
 */
export const isCancelled = query({
  args: { spaceId: v.string(), chainId: v.string() },
  returns: v.boolean(),
  handler: async (ctx, args) => {
    const inflight = await ctx.db
      .query("inflight")
      .withIndex("by_space", (q) => q.eq("spaceId", args.spaceId))
      .unique();
    if (!inflight) {
      return true;
    }
    // A different chain owns the space now.
    if (inflight.chainId !== args.chainId) {
      return true;
    }
    if (!(inflight.cancelledAt && inflight.chainStartedAt)) {
      return false;
    }
    return inflight.cancelledAt > inflight.chainStartedAt;
  },
});

/** Mark a chain's drained messages handled. Called when a turn completes. */
export const completeChain = mutation({
  args: { spaceId: v.string(), chainId: v.string() },
  returns: v.null(),
  handler: async (ctx, args) => {
    const rows = await ctx.db
      .query("inbound")
      .withIndex("by_chain", (q) => q.eq("chainId", args.chainId))
      .collect();
    for (const row of rows) {
      if (row.status === "drained") {
        await ctx.db.patch(row._id, { status: "handled" as const });
      }
    }
    const inflight = await getInflight(ctx, args.spaceId);
    if (inflight?.chainId === args.chainId) {
      await ctx.db.patch(inflight._id, { handlerJobId: undefined });
    }
    return null;
  },
});

/** Test/ops helper: force-cancel the current turn for a space. */
export const cancel = mutation({
  args: { spaceId: v.string() },
  returns: v.union(v.null(), v.string()),
  handler: async (ctx, args) => {
    const chainId = await cancelCurrentChain(ctx, args.spaceId, Date.now());
    return chainId ?? null;
  },
});

export { batchMessageValidator, createFunctionHandle };

import { v } from "convex/values";
import { internal } from "./_generated/api.js";
import type { Doc } from "./_generated/dataModel.js";
import {
  type MutationCtx,
  internalMutation,
  mutation,
  query,
} from "./_generated/server.js";

/**
 * The outbound half: a durable outbox with deterministic idempotency keys.
 *
 * Every row carries a `clientGuid` derived from `(chainId, seq)`. It travels to
 * the provider as the send's idempotency key, so a retry — whether ours or the
 * scheduler's — re-uses the same guid and cannot post the message twice. That
 * matters most on the failure mode that actually bites in production: the send
 * succeeded but the acknowledgement was lost.
 */

const MAX_ATTEMPTS = 5;
const BASE_RETRY_DELAY_MS = 1000;
const RETRY_BACKOFF_FACTOR = 4;

export const sendKind = v.union(
  v.literal("send"),
  v.literal("reply"),
  v.literal("react"),
  v.literal("markRead"),
  v.literal("typing")
);

const chainIsLive = async (
  ctx: MutationCtx,
  spaceId: string,
  chainId: string | undefined
): Promise<boolean> => {
  if (!chainId) {
    // A send with no chain (e.g. a proactive outbound message) is never
    // subject to conversational cancellation.
    return true;
  }
  const inflight = await ctx.db
    .query("inflight")
    .withIndex("by_space", (q) => q.eq("spaceId", spaceId))
    .unique();
  if (!inflight || inflight.chainId !== chainId) {
    return false;
  }
  if (!(inflight.cancelledAt && inflight.chainStartedAt)) {
    return true;
  }
  return inflight.cancelledAt <= inflight.chainStartedAt;
};

/**
 * Queue one outbound action.
 *
 * Rejects (without writing) when the queueing chain has already been
 * superseded — the guard that stops a cancelled turn from talking over the
 * turn that replaced it. `pacingMs` staggers a multi-message reply so it reads
 * like typing rather than a wall of text arriving at once.
 */
export const enqueue = mutation({
  args: {
    spaceId: v.string(),
    chainId: v.optional(v.string()),
    kind: sendKind,
    content: v.optional(v.any()),
    targetMessageId: v.optional(v.string()),
    reaction: v.optional(v.string()),
    pacingMs: v.optional(v.number()),
    sender: v.optional(v.string()),
  },
  returns: v.object({
    queued: v.boolean(),
    clientGuid: v.optional(v.string()),
    reason: v.optional(v.string()),
  }),
  handler: async (ctx, args) => {
    if (!(await chainIsLive(ctx, args.spaceId, args.chainId))) {
      return { queued: false, reason: "chain-cancelled" };
    }

    const priorForChain = args.chainId
      ? await ctx.db
          .query("outbox")
          .withIndex("by_chain", (q) => q.eq("chainId", args.chainId))
          .collect()
      : [];
    const seq = priorForChain.length;
    const now = Date.now();
    // Deterministic: the same (chain, seq) always yields the same guid, which
    // is what makes a replayed send collapse instead of duplicating.
    const clientGuid = `${args.chainId ?? `${args.spaceId}:${now}`}#${seq}`;

    const existing = await ctx.db
      .query("outbox")
      .withIndex("by_guid", (q) => q.eq("clientGuid", clientGuid))
      .unique();
    if (existing) {
      return { queued: false, clientGuid, reason: "duplicate" };
    }

    const rowId = await ctx.db.insert("outbox", {
      spaceId: args.spaceId,
      ...(args.chainId === undefined ? {} : { chainId: args.chainId }),
      seq,
      clientGuid,
      kind: args.kind,
      ...(args.content === undefined ? {} : { content: args.content }),
      ...(args.targetMessageId === undefined
        ? {}
        : { targetMessageId: args.targetMessageId }),
      ...(args.reaction === undefined ? {} : { reaction: args.reaction }),
      status: "pending" as const,
      attempts: 0,
      queuedAt: now,
    });

    if (args.sender) {
      const jobId = await ctx.scheduler.runAfter(
        args.pacingMs ?? 0,
        internal.outbox.deliver,
        { rowId, sender: args.sender }
      );
      await ctx.db.patch(rowId, { jobId });
    }

    return { queued: true, clientGuid };
  },
});

/**
 * Hand one outbox row to the app-provided sender.
 *
 * The sender is a function handle for an action the app owns, because the
 * iMessage transport is gRPC and only Convex's Node runtime can speak it. The
 * component stays transport-agnostic: swap in a fetch-based sender and nothing
 * here changes.
 */
export const deliver = internalMutation({
  args: { rowId: v.id("outbox"), sender: v.string() },
  returns: v.null(),
  handler: async (ctx, args) => {
    const row = await ctx.db.get(args.rowId);
    if (!row || row.status !== "pending") {
      return null;
    }
    if (!(await chainIsLive(ctx, row.spaceId, row.chainId))) {
      await ctx.db.patch(row._id, { status: "cancelled" as const });
      return null;
    }

    await ctx.db.patch(row._id, {
      status: "sending" as const,
      attempts: row.attempts + 1,
    });

    const space = await ctx.db
      .query("spaces")
      .withIndex("by_space", (q) => q.eq("spaceId", row.spaceId))
      .unique();

    await ctx.scheduler.runAfter(
      0,
      args.sender as Parameters<typeof ctx.scheduler.runAfter>[1],
      {
        rowId: row._id,
        spaceId: row.spaceId,
        phone: space?.phone,
        clientGuid: row.clientGuid,
        kind: row.kind,
        content: row.content,
        targetMessageId: row.targetMessageId,
        reaction: row.reaction,
      }
    );
    return null;
  },
});

/** Record the sender's verdict for one row; retries with backoff on failure. */
export const settle = mutation({
  args: {
    rowId: v.id("outbox"),
    ok: v.boolean(),
    providerMessageId: v.optional(v.string()),
    error: v.optional(v.string()),
    sender: v.optional(v.string()),
  },
  returns: v.null(),
  handler: async (ctx, args) => {
    const row = await ctx.db.get(args.rowId);
    if (!row) {
      return null;
    }
    if (args.ok) {
      await ctx.db.patch(row._id, {
        status: "sent" as const,
        sentAt: Date.now(),
        ...(args.providerMessageId === undefined
          ? {}
          : { providerMessageId: args.providerMessageId }),
      });
      return null;
    }

    const exhausted = row.attempts >= MAX_ATTEMPTS;
    if (exhausted || !args.sender) {
      await ctx.db.patch(row._id, {
        status: "failed" as const,
        ...(args.error === undefined ? {} : { lastError: args.error }),
      });
      return null;
    }

    // Same clientGuid on the retry, so a send that actually landed before the
    // error is deduped provider-side instead of posting twice.
    const delay = BASE_RETRY_DELAY_MS * RETRY_BACKOFF_FACTOR ** row.attempts;
    const jobId = await ctx.scheduler.runAfter(delay, internal.outbox.deliver, {
      rowId: row._id,
      sender: args.sender,
    });
    await ctx.db.patch(row._id, {
      status: "pending" as const,
      jobId,
      ...(args.error === undefined ? {} : { lastError: args.error }),
    });
    return null;
  },
});

const outboxRow = v.object({
  clientGuid: v.string(),
  kind: v.string(),
  status: v.string(),
  attempts: v.number(),
  queuedAt: v.number(),
  sentAt: v.optional(v.number()),
  providerMessageId: v.optional(v.string()),
  lastError: v.optional(v.string()),
});

const toOutboxRow = (row: Doc<"outbox">) => ({
  clientGuid: row.clientGuid,
  kind: row.kind,
  status: row.status,
  attempts: row.attempts,
  queuedAt: row.queuedAt,
  ...(row.sentAt === undefined ? {} : { sentAt: row.sentAt }),
  ...(row.providerMessageId === undefined
    ? {}
    : { providerMessageId: row.providerMessageId }),
  ...(row.lastError === undefined ? {} : { lastError: row.lastError }),
});

/** Outbox rows for a space — delivery status and the failure audit trail. */
export const list = query({
  args: { spaceId: v.string(), limit: v.optional(v.number()) },
  returns: v.array(outboxRow),
  handler: async (ctx, args) => {
    const rows = await ctx.db
      .query("outbox")
      .withIndex("by_space_status", (q) => q.eq("spaceId", args.spaceId))
      .order("desc")
      .take(args.limit ?? 50);
    return rows.reverse().map(toOutboxRow);
  },
});

import {
  createFunctionHandle,
  type FunctionReference,
  type GenericActionCtx,
  type GenericDataModel,
  type GenericMutationCtx,
  type GenericQueryCtx,
  type HttpRouter,
  httpActionGeneric,
} from "convex/server";
import { headerRecord, parseWebhook } from "../shared/wire.js";
import type { ComponentApi } from "./component.js";

/**
 * App-facing client for the Spectrum component.
 *
 * Wraps the component's functions so app code never addresses them directly,
 * and runs in the app's own environment — which is what gives it access to
 * `process.env.SPECTRUM_WEBHOOK_SECRET` (a component's HTTP actions cannot read
 * the app's env vars).
 */

export const DEFAULT_WEBHOOK_PATH = "/spectrum/webhook";
const DEFAULT_DEBOUNCE_MS = 5000;
const OK_STATUS = 200;
const SERVER_ERROR_STATUS = 500;

/** One inbound message as handed to a batch handler. */
export interface BatchMessage {
  messageId: string;
  senderId?: string;
  content: unknown;
  timestamp?: string;
}

/** The batch a handler is invoked with — one conversational turn. */
export interface Batch {
  spaceId: string;
  chainId: string;
  /** Messages from this burst, oldest first. */
  messages: BatchMessage[];
  /**
   * Messages a previous, cancelled turn had already drained. Present them as
   * earlier context rather than fresh input — the user has been waiting on
   * these longer than the ones in `messages`.
   */
  carried: BatchMessage[];
}

type AnyCtx =
  | GenericQueryCtx<GenericDataModel>
  | GenericMutationCtx<GenericDataModel>
  | GenericActionCtx<GenericDataModel>;
type RunMutationCtx =
  | GenericMutationCtx<GenericDataModel>
  | GenericActionCtx<GenericDataModel>;

export interface SpectrumOptions {
  /**
   * The app function invoked once per settled burst. Usually an
   * `internalAction` so it can call an LLM.
   */
  onBatch?: FunctionReference<"action" | "mutation", "internal" | "public">;
  /**
   * The app action that actually talks to the provider. Required to deliver
   * sends; without it, outbox rows queue durably but never go out.
   */
  sender?: FunctionReference<"action" | "mutation", "internal" | "public">;
  /**
   * How long to wait for a burst to settle before handling it. A few seconds
   * covers the "hey" → "wait" → "actually" pattern.
   *
   * @default 5000
   */
  debounceMs?: number;
  /** Delay between consecutive sends in one turn, so replies don't land at once. */
  pacingMs?: number;
  /**
   * Signing secret for native Spectrum webhooks. Falls back to
   * `process.env.SPECTRUM_WEBHOOK_SECRET`.
   */
  webhookSecret?: string;
  /** @default "/spectrum/webhook" */
  webhookPath?: string;
}

export class Spectrum {
  constructor(
    public component: ComponentApi,
    public options: SpectrumOptions = {}
  ) {}

  private get debounceMs(): number {
    return this.options.debounceMs ?? DEFAULT_DEBOUNCE_MS;
  }

  private secret(): string | undefined {
    return (
      this.options.webhookSecret ?? process.env.SPECTRUM_WEBHOOK_SECRET
    );
  }

  private async handleRef(): Promise<string | undefined> {
    return this.options.onBatch
      ? await createFunctionHandle(this.options.onBatch)
      : undefined;
  }

  private async senderRef(): Promise<string | undefined> {
    return this.options.sender
      ? await createFunctionHandle(this.options.sender)
      : undefined;
  }

  /**
   * Mount the webhook endpoint.
   *
   * The handler verifies and persists the delivery *before* answering 200, so
   * an acknowledged message is already durable. It deliberately does no work
   * after the response — on Convex the isolate is frozen once the response is
   * returned, which is exactly the trap `app.webhook()`'s fire-and-forget
   * handler falls into on serverless.
   */
  registerRoutes(http: HttpRouter, opts: { path?: string } = {}): void {
    const path =
      opts.path ?? this.options.webhookPath ?? DEFAULT_WEBHOOK_PATH;

    http.route({
      path,
      method: "POST",
      handler: httpActionGeneric(async (ctx, request) => {
        const secret = this.secret();
        if (!secret) {
          return new Response(
            "webhook secret not configured (set SPECTRUM_WEBHOOK_SECRET)",
            { status: SERVER_ERROR_STATUS }
          );
        }

        // Read the body ONCE, as bytes. The HMAC covers the exact bytes on the
        // wire, so parsing to JSON and re-encoding would break verification.
        const bodyBytes = new Uint8Array(await request.arrayBuffer());
        const outcome = await parseWebhook({
          bodyBytes,
          headers: headerRecord(request.headers),
          secret,
        });

        if (!outcome.ok) {
          return new Response(outcome.reason, { status: outcome.status });
        }

        const { message } = outcome;
        await ctx.runMutation(this.component.inbound.enqueue, {
          spaceId: message.spaceId,
          messageId: message.messageId,
          platform: message.platform,
          ...(message.senderId === undefined
            ? {}
            : { senderId: message.senderId }),
          content: message.content,
          ...(message.timestamp === undefined
            ? {}
            : { timestamp: message.timestamp }),
          raw: message.raw,
          debounceMs: this.debounceMs,
          ...((await this.handleRef()) === undefined
            ? {}
            : { onBatch: await this.handleRef() }),
        });

        return new Response("ok", { status: OK_STATUS });
      }),
    });
  }

  /**
   * Has this turn been superseded by a newer message?
   *
   * `ctx.scheduler.cancel` can't stop an action that is already running, so a
   * handler doing slow work (generating, sending) should poll this between
   * steps and return early when it flips.
   */
  async isCancelled(
    ctx: AnyCtx,
    args: { spaceId: string; chainId: string }
  ): Promise<boolean> {
    return await ctx.runQuery(this.component.pipeline.isCancelled, args);
  }

  /** Queue an outbound message. Rejected if the chain was superseded. */
  async send(
    ctx: RunMutationCtx,
    args: {
      spaceId: string;
      content: unknown;
      chainId?: string;
      pacingMs?: number;
    }
  ): Promise<{ queued: boolean; clientGuid?: string; reason?: string }> {
    return await ctx.runMutation(this.component.outbox.enqueue, {
      spaceId: args.spaceId,
      kind: "send" as const,
      content: args.content,
      ...(args.chainId === undefined ? {} : { chainId: args.chainId }),
      pacingMs: args.pacingMs ?? this.options.pacingMs ?? 0,
      ...((await this.senderRef()) === undefined
        ? {}
        : { sender: await this.senderRef() }),
    });
  }

  /** Queue a threaded reply to a specific message. */
  async reply(
    ctx: RunMutationCtx,
    args: {
      spaceId: string;
      targetMessageId: string;
      content: unknown;
      chainId?: string;
      pacingMs?: number;
    }
  ): Promise<{ queued: boolean; clientGuid?: string; reason?: string }> {
    return await ctx.runMutation(this.component.outbox.enqueue, {
      spaceId: args.spaceId,
      kind: "reply" as const,
      content: args.content,
      targetMessageId: args.targetMessageId,
      ...(args.chainId === undefined ? {} : { chainId: args.chainId }),
      pacingMs: args.pacingMs ?? this.options.pacingMs ?? 0,
      ...((await this.senderRef()) === undefined
        ? {}
        : { sender: await this.senderRef() }),
    });
  }

  /** Queue a tapback on a message. */
  async react(
    ctx: RunMutationCtx,
    args: {
      spaceId: string;
      targetMessageId: string;
      reaction: string;
      chainId?: string;
    }
  ): Promise<{ queued: boolean; clientGuid?: string; reason?: string }> {
    return await ctx.runMutation(this.component.outbox.enqueue, {
      spaceId: args.spaceId,
      kind: "react" as const,
      targetMessageId: args.targetMessageId,
      reaction: args.reaction,
      ...(args.chainId === undefined ? {} : { chainId: args.chainId }),
      ...((await this.senderRef()) === undefined
        ? {}
        : { sender: await this.senderRef() }),
    });
  }

  /** Mark a conversation read. */
  async markRead(
    ctx: RunMutationCtx,
    args: { spaceId: string; chainId?: string }
  ): Promise<{ queued: boolean; clientGuid?: string; reason?: string }> {
    return await ctx.runMutation(this.component.outbox.enqueue, {
      spaceId: args.spaceId,
      kind: "markRead" as const,
      ...(args.chainId === undefined ? {} : { chainId: args.chainId }),
      ...((await this.senderRef()) === undefined
        ? {}
        : { sender: await this.senderRef() }),
    });
  }

  /** Mark a turn's messages handled. Call when the handler finishes. */
  async completeChain(
    ctx: RunMutationCtx,
    args: { spaceId: string; chainId: string }
  ): Promise<void> {
    await ctx.runMutation(this.component.pipeline.completeChain, args);
  }

  /** Routing record for a space (`phone`, chat type), or `null`. */
  async getSpace(
    ctx: AnyCtx,
    args: { spaceId: string }
  ): Promise<{
    spaceId: string;
    platform: string;
    phone?: string;
    type?: "dm" | "group";
    lastInboundAt: number;
  } | null> {
    return await ctx.runQuery(this.component.inbound.getSpace, args);
  }

  /** Recent inbound messages for a space, oldest first. */
  async listMessages(
    ctx: AnyCtx,
    args: { spaceId: string; limit?: number }
  ): Promise<BatchMessage[]> {
    return await ctx.runQuery(this.component.inbound.listMessages, args);
  }

  /** Outbox rows for a space — delivery status and failure audit trail. */
  async listOutbox(
    ctx: AnyCtx,
    args: { spaceId: string; limit?: number }
  ): Promise<
    {
      clientGuid: string;
      kind: string;
      status: string;
      attempts: number;
      queuedAt: number;
      sentAt?: number;
      providerMessageId?: string;
      lastError?: string;
    }[]
  > {
    return await ctx.runQuery(this.component.outbox.list, args);
  }

  /** Report a send's outcome back to the outbox. Called by the sender action. */
  async settle(
    ctx: RunMutationCtx,
    args: {
      rowId: string;
      ok: boolean;
      providerMessageId?: string;
      error?: string;
    }
  ): Promise<void> {
    await ctx.runMutation(this.component.outbox.settle, {
      ...args,
      ...((await this.senderRef()) === undefined
        ? {}
        : { sender: await this.senderRef() }),
    });
  }
}

export type { ComponentApi } from "./component.js";
export { headerRecord, parseWebhook } from "../shared/wire.js";

import type { FunctionReference } from "convex/server";

/**
 * The component's public function surface, as seen from the installing app.
 *
 * Hand-written rather than re-exported from the component's `_generated/api`
 * because the app addresses these through `components.spectrum.*`, whose type
 * is produced by the *app's* codegen. Declaring the shape here lets the client
 * class stay fully typed without the app having to thread generated types back
 * into the package.
 */

type Mutation<Args, Return> = FunctionReference<
  "mutation",
  "internal",
  Args,
  Return
>;
type Query<Args, Return> = FunctionReference<"query", "internal", Args, Return>;

export interface EnqueueResult {
  queued: boolean;
  clientGuid?: string;
  reason?: string;
}

export interface SpaceRecord {
  spaceId: string;
  platform: string;
  phone?: string;
  type?: "dm" | "group";
  lastInboundAt: number;
}

export interface StoredMessage {
  messageId: string;
  senderId?: string;
  content: unknown;
  timestamp?: string;
  receivedAt: number;
  status: string;
}

export interface OutboxRecord {
  clientGuid: string;
  kind: string;
  status: string;
  attempts: number;
  queuedAt: number;
  sentAt?: number;
  providerMessageId?: string;
  lastError?: string;
}

export interface ComponentApi {
  inbound: {
    enqueue: Mutation<
      {
        spaceId: string;
        messageId: string;
        platform: string;
        senderId?: string;
        content: unknown;
        timestamp?: string;
        raw?: unknown;
        phone?: string;
        spaceType?: "dm" | "group";
        debounceMs?: number;
        onBatch?: string;
      },
      { deduped: boolean; cancelledChain?: string }
    >;
    getSpace: Query<{ spaceId: string }, SpaceRecord | null>;
    listMessages: Query<
      { spaceId: string; limit?: number },
      StoredMessage[]
    >;
  };
  pipeline: {
    isCancelled: Query<{ spaceId: string; chainId: string }, boolean>;
    completeChain: Mutation<{ spaceId: string; chainId: string }, null>;
    cancel: Mutation<{ spaceId: string }, string | null>;
  };
  outbox: {
    enqueue: Mutation<
      {
        spaceId: string;
        chainId?: string;
        kind: "send" | "reply" | "react" | "markRead" | "typing";
        content?: unknown;
        targetMessageId?: string;
        reaction?: string;
        pacingMs?: number;
        sender?: string;
      },
      EnqueueResult
    >;
    settle: Mutation<
      {
        rowId: string;
        ok: boolean;
        providerMessageId?: string;
        error?: string;
        sender?: string;
      },
      null
    >;
    list: Query<{ spaceId: string; limit?: number }, OutboxRecord[]>;
  };
}

import { convexTest } from "convex-test";
import { describe, expect, it } from "vitest";
import { api } from "../src/component/_generated/api.js";
import schema from "../src/component/schema.js";

/**
 * Pipeline behavior tests, run against the component's own schema in
 * `convex-test`'s in-memory backend.
 *
 * These target the rules that are easy to get subtly wrong and expensive to
 * discover in production: at-least-once dedupe, the debounce reset, the
 * carry-forward rule, and the per-chain (not per-space) cancellation check.
 */

// `import.meta.glob` is how convex-test discovers the function modules. The
// component's files live outside a conventional `convex/` dir, so the glob is
// pointed at them explicitly.
const modules = import.meta.glob("../src/component/**/*.ts");

const setup = () => convexTest(schema, modules);

const message = (overrides: Record<string, unknown> = {}) => ({
  spaceId: "chat-1",
  messageId: "m1",
  platform: "imessage",
  senderId: "u1",
  content: { type: "text", text: "hey" },
  ...overrides,
});

describe("inbound.enqueue", () => {
  it("stores a verified message and registers the space", async () => {
    const t = setup();
    const result = await t.mutation(api.inbound.enqueue, message());
    expect(result.deduped).toBe(false);

    const space = await t.query(api.inbound.getSpace, { spaceId: "chat-1" });
    expect(space?.platform).toBe("imessage");

    const stored = await t.query(api.inbound.listMessages, {
      spaceId: "chat-1",
    });
    expect(stored).toHaveLength(1);
    expect(stored[0]?.messageId).toBe("m1");
    expect(stored[0]?.status).toBe("queued");
  });

  it("dedupes a redelivered message id without a second row", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message());
    const second = await t.mutation(api.inbound.enqueue, message());

    expect(second.deduped).toBe(true);
    const stored = await t.query(api.inbound.listMessages, {
      spaceId: "chat-1",
    });
    expect(stored).toHaveLength(1);
  });

  it("keeps a learned phone when a later delivery omits it", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message({ phone: "+15551234567" }));
    await t.mutation(api.inbound.enqueue, message({ messageId: "m2" }));

    const space = await t.query(api.inbound.getSpace, { spaceId: "chat-1" });
    expect(space?.phone).toBe("+15551234567");
  });
});

describe("debounce and flush", () => {
  it("handles a burst as one batch after the window settles", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message({ messageId: "m1" }));
    await t.mutation(api.inbound.enqueue, message({ messageId: "m2" }));
    await t.mutation(
      api.inbound.enqueue,
      message({ messageId: "m3", debounceMs: 5000 })
    );

    // Nothing has been drained yet — the timer is still running.
    let stored = await t.query(api.inbound.listMessages, {
      spaceId: "chat-1",
    });
    expect(stored.every((m) => m.status === "queued")).toBe(true);

    await t.finishAllScheduledFunctions(() => {
      // Advance past the debounce window.
    });

    stored = await t.query(api.inbound.listMessages, { spaceId: "chat-1" });
    expect(stored).toHaveLength(3);
    // One flush drained the whole burst into a single chain.
    expect(stored.every((m) => m.status === "drained")).toBe(true);
  });
});

describe("cancellation and carry-forward", () => {
  it("carries drained messages forward when a chain is superseded", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message({ messageId: "m1" }));
    await t.finishAllScheduledFunctions(() => {
      // Let the first burst flush and take ownership of the space.
    });

    // A new message lands mid-turn: the chain is cancelled and its drained
    // rows must not be lost.
    await t.mutation(api.inbound.enqueue, message({ messageId: "m2" }));

    const carried = await t.run(async (ctx) =>
      await ctx.db.query("carried").collect()
    );
    expect(carried).toHaveLength(1);
    expect(carried[0]?.messageId).toBe("m1");
  });

  it("prepends carried messages into the next flush", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message({ messageId: "m1" }));
    await t.finishAllScheduledFunctions(() => {
      // First turn takes ownership.
    });
    await t.mutation(api.inbound.enqueue, message({ messageId: "m2" }));
    await t.finishAllScheduledFunctions(() => {
      // Second turn drains m2 and consumes the carried m1.
    });

    // The carry table is drained by the flush that consumed it.
    const carried = await t.run(async (ctx) =>
      await ctx.db.query("carried").collect()
    );
    expect(carried).toHaveLength(0);
  });

  it("reports a superseded chain as cancelled, and a live one as not", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message({ messageId: "m1" }));
    await t.finishAllScheduledFunctions(() => {
      // Establish a chain.
    });

    const chainId = await t.run(async (ctx) => {
      const inflight = await ctx.db.query("inflight").first();
      return inflight?.chainId;
    });
    expect(chainId).toBeDefined();

    expect(
      await t.query(api.pipeline.isCancelled, {
        spaceId: "chat-1",
        chainId: chainId as string,
      })
    ).toBe(false);

    await t.mutation(api.pipeline.cancel, { spaceId: "chat-1" });

    expect(
      await t.query(api.pipeline.isCancelled, {
        spaceId: "chat-1",
        chainId: chainId as string,
      })
    ).toBe(true);
  });

  it("treats an unknown chain as cancelled", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message());
    expect(
      await t.query(api.pipeline.isCancelled, {
        spaceId: "chat-1",
        chainId: "some-chain-that-never-existed",
      })
    ).toBe(true);
  });
});

describe("outbox", () => {
  it("assigns deterministic per-chain idempotency keys", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message());
    await t.finishAllScheduledFunctions(() => {
      // Establish a chain to queue sends against.
    });
    const chainId = (await t.run(async (ctx) => {
      const inflight = await ctx.db.query("inflight").first();
      return inflight?.chainId;
    })) as string;

    const first = await t.mutation(api.outbox.enqueue, {
      spaceId: "chat-1",
      chainId,
      kind: "send" as const,
      content: { type: "text", text: "one" },
    });
    const second = await t.mutation(api.outbox.enqueue, {
      spaceId: "chat-1",
      chainId,
      kind: "send" as const,
      content: { type: "text", text: "two" },
    });

    expect(first.clientGuid).toBe(`${chainId}#0`);
    expect(second.clientGuid).toBe(`${chainId}#1`);
  });

  it("refuses to queue a send from a superseded chain", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message());
    await t.finishAllScheduledFunctions(() => {
      // Establish a chain.
    });
    const chainId = (await t.run(async (ctx) => {
      const inflight = await ctx.db.query("inflight").first();
      return inflight?.chainId;
    })) as string;

    await t.mutation(api.pipeline.cancel, { spaceId: "chat-1" });

    const result = await t.mutation(api.outbox.enqueue, {
      spaceId: "chat-1",
      chainId,
      kind: "send" as const,
      content: { type: "text", text: "too late" },
    });
    expect(result.queued).toBe(false);
    expect(result.reason).toBe("chain-cancelled");
  });

  it("cancels pending sends belonging to a superseded chain", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message());
    await t.finishAllScheduledFunctions(() => {
      // Establish a chain.
    });
    const chainId = (await t.run(async (ctx) => {
      const inflight = await ctx.db.query("inflight").first();
      return inflight?.chainId;
    })) as string;

    await t.mutation(api.outbox.enqueue, {
      spaceId: "chat-1",
      chainId,
      kind: "send" as const,
      content: { type: "text", text: "queued" },
    });
    await t.mutation(api.pipeline.cancel, { spaceId: "chat-1" });

    const rows = await t.query(api.outbox.list, { spaceId: "chat-1" });
    expect(rows).toHaveLength(1);
    expect(rows[0]?.status).toBe("cancelled");
  });

  it("allows a chainless send regardless of conversational state", async () => {
    const t = setup();
    await t.mutation(api.inbound.enqueue, message());
    await t.finishAllScheduledFunctions(() => {
      // Establish then kill a chain.
    });
    await t.mutation(api.pipeline.cancel, { spaceId: "chat-1" });

    const result = await t.mutation(api.outbox.enqueue, {
      spaceId: "chat-1",
      kind: "send" as const,
      content: { type: "text", text: "proactive" },
    });
    expect(result.queued).toBe(true);
  });
});

