import { spectrum } from "./spectrum";

/**
 * The app's batch handler — one invocation per conversational turn.
 *
 * `carried` holds messages an earlier, cancelled turn had already drained.
 * They're older than `messages`, so they're presented as prior context rather
 * than as part of the current question.
 */
export const respond = internalAction({
  args: {
    spaceId: v.string(),
    chainId: v.string(),
    messages: v.array(v.any()),
    carried: v.array(v.any()),
  },
  returns: v.null(),
  handler: async (ctx, args) => {
    const text = (m: { content?: unknown }): string => {
      const content = m.content as { type?: string; text?: string } | undefined;
      return content?.type === "text" ? (content.text ?? "") : `[${content?.type ?? "unknown"}]`;
    };

    const history = args.carried.map((m) => `[Earlier message] ${text(m)}`);
    const current = args.messages.map(text);
    const prompt = [...history, ...current].join("\n");

    // A real agent calls an LLM here. Anything slow should re-check
    // `isCancelled` afterwards, because a new message may have arrived while
    // it was thinking — the scheduler cannot interrupt a running action.
    const reply = `You said: ${prompt}`;

    if (await spectrum.isCancelled(ctx, args)) {
      return null;
    }

    await spectrum.send(ctx, {
      spaceId: args.spaceId,
      chainId: args.chainId,
      content: { type: "text", text: reply },
    });
    await spectrum.completeChain(ctx, args);
    return null;
  },
});
